using MediatR; using Microsoft.EntityFrameworkCore; using InventorySystem.Application.DTOs; using InventorySystem.Application.Interfaces;
namespace InventorySystem.Application.Features.Dashboard.Queries;
public record GetDashboardSummaryQuery : IRequest<DashboardSummaryDto>;
public class GetDashboardSummaryQueryHandler(IAppDbContext db) : IRequestHandler<GetDashboardSummaryQuery,DashboardSummaryDto> { public async Task<DashboardSummaryDto> Handle(GetDashboardSummaryQuery r,CancellationToken ct){ var today=DateTime.UtcNow.Date; var totalProducts=await db.Products.CountAsync(x=>!x.IsDeleted,ct); var totalStockValue=await db.StockItems.Where(x=>!x.IsDeleted).SumAsync(x=>(decimal?)x.Quantity*x.Product.PurchasePrice,ct)??0m; var lowStockCount=await db.StockItems.CountAsync(x=>!x.IsDeleted&&x.Quantity<=x.Product.MinimumStock,ct); var todayMovements=await db.StockMovements.CountAsync(x=>!x.IsDeleted&&x.Date>=today,ct); return new DashboardSummaryDto(totalProducts,totalStockValue,lowStockCount,todayMovements); } }
